"""Standalone escaped HTML and machine-readable evidence from the same comparison."""
from pathlib import Path
from html import escape
from statistics import mean
import json
import os
from .config import GuardError


def atomic_text(path: Path, text: str):
    path.parent.mkdir(parents=True, exist_ok=True)
    temp=path.with_name(path.name+'.tmp-'+str(os.getpid()))
    try:
        temp.write_text(text, encoding='utf-8'); temp.replace(path)
    finally:
        if temp.exists(): temp.unlink()

def percent(value): return 'Not available' if value is None else f'{100*value:.1f}%'
def safe(value): return escape(str(value), quote=True)

def render_html(baseline, candidate, comparison, history, drift) -> str:
    old={c.case_id:c for c in baseline.cases}; new={c.case_id:c for c in candidate.cases}
    def output(c):
        if c.error: return '<span class="error">'+safe(c.error)+'</span>'
        if not c.prediction: return 'No output'
        return '<b>'+safe(c.prediction.category)+'</b><p>'+safe(c.prediction.summary)+'</p>'
    rows=''.join('<tr><th scope="row"><code>'+safe(i)+'</code><small>Expected: '+safe(old[i].expected.category)+'</small></th><td>'+output(old[i])+'</td><td>'+output(new[i])+'</td></tr>' for i in comparison['regressions'])
    if not rows: rows='<tr><td colspan="3">No pass-to-fail regressions in this comparison.</td></tr>'
    cats=''.join('<tr><th scope="row">'+safe(k)+'</th><td>'+str(v['baseline']['n'])+'</td><td>'+percent(v['baseline']['accuracy'])+'</td><td>'+percent(v['candidate']['accuracy'])+'</td><td>'+('—' if v['delta'] is None else f"{100*v['delta']:+.1f} pp")+'</td></tr>' for k,v in comparison['per_category'].items())
    allcases=''.join('<tr><th scope="row"><code>'+safe(c.case_id)+'</code><small>'+safe(c.difficulty)+'</small></th><td>'+('Pass' if old[c.case_id].passed else 'Fail')+'</td><td>'+('Error: '+safe(c.error) if c.error else 'Pass' if c.passed else 'Fail')+'</td><td>'+('Not judged' if c.summary_score is None else str(c.summary_score)+'/5')+'</td><td>'+('Not measured' if not c.classification or c.classification.elapsed_ms is None else f'{c.classification.elapsed_ms:.1f} ms')+'</td></tr>' for c in candidate.cases)
    trend=[r for r in history if r.created_at<=candidate.created_at and r.dataset_hash==candidate.dataset_hash and r.provider==candidate.provider and r.judge_policy==candidate.judge_policy][-20:]
    if candidate.id not in {r.id for r in trend}: trend.append(candidate)
    if trend:
        points=' '.join(f'{40+i*(640/max(1,len(trend)-1)):.1f},{180-r.summary["pass_rate"]*140:.1f}' for i,r in enumerate(trend))
        chart='<svg viewBox="0 0 720 210" role="img" aria-label="Pass rate across compatible saved runs"><path d="M40 25V180H690" fill="none" stroke="#c5cdd5"/><text x="0" y="45">100%</text><text x="12" y="183">0%</text><polyline points="'+points+'" fill="none" stroke="#2d6957" stroke-width="2.5"/>'+''.join(f'<circle cx="{40+i*(640/max(1,len(trend)-1)):.1f}" cy="{180-r.summary["pass_rate"]*140:.1f}" r="4" fill="#2d6957"><title>{safe(r.prompt_version)}: {percent(r.summary["pass_rate"])}</title></circle>' for i,r in enumerate(trend))+'</svg>'
    else: chart='<p>No history available.</p>'
    fixture=candidate.provenance=='synthetic_fixture' or candidate.provider=='replay'
    banner='Controlled synthetic fixtures and recorded outputs. These numbers test the evaluator; they are not measured live-model quality.' if fixture else 'Human-reviewed dataset declaration. Summary ratings are model judgments, not independently verified truth.'
    delta=100*comparison['delta']; status=comparison['status']
    metadata=f'<dl><dt>Baseline</dt><dd>{safe(baseline.prompt_version)} · {safe(baseline.model)} · <code>{safe(baseline.id)}</code></dd><dt>Candidate</dt><dd>{safe(candidate.prompt_version)} · {safe(candidate.model)} · <code>{safe(candidate.id)}</code></dd><dt>Dataset</dt><dd>{safe(candidate.dataset_version)} · {len(candidate.cases)} cases · <code>{safe(candidate.dataset_hash)}</code></dd><dt>Scoring</dt><dd>{safe(candidate.judge_policy)} · minimum summary score {candidate.min_summary_score}/5</dd><dt>Time</dt><dd>{safe(candidate.created_at)}</dd></dl>'
    measurements=''.join('<tr><th scope="row">'+label+'</th><td>'+safe(baseline.summary[key] if baseline.summary[key] is not None else 'Not measured')+'</td><td>'+safe(candidate.summary[key] if candidate.summary[key] is not None else 'Not measured')+'</td></tr>' for key,label in [('summary_mean','Mean summary rating / 5'),('classification_p95_ms','Classification latency p95 / ms'),('input_tokens','Observed input tokens'),('output_tokens','Observed output tokens'),('requests_attempted','Request attempts'),('errors','Operational errors')])
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ModelGuard · Regression report</title><style>
    *{{box-sizing:border-box}}body{{margin:0;color:#28333d;background:#f8f9fb;font:14px/1.65 -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif}}header{{background:#fff;border-bottom:1px solid #dce2e8;padding:18px 6%;display:flex;justify-content:space-between}}main{{max-width:1150px;margin:0 auto;padding:35px 25px}}h1{{font-size:30px;letter-spacing:-1px;margin:0 0 8px}}h2{{font-size:18px;margin:30px 0 13px}}p{{margin:6px 0}}.status{{font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:1px}}.critical,.error{{color:#aa4939}}.warning{{color:#9b762d}}.pass{{color:#377a5c}}.banner{{background:#f7f0df;border:1px solid #e9dec1;padding:13px 17px;border-radius:5px;margin:20px 0}}.metrics{{display:grid;grid-template-columns:repeat(4,1fr);gap:0;background:#fff;border:1px solid #dce2e8;border-radius:5px;margin:25px 0}}.metric{{padding:18px 22px;border-right:1px solid #e6eaef}}.metric:last-child{{border:0}}.metric strong{{display:block;font-size:26px;letter-spacing:-1px}}.metric span,small{{font-size:12px;color:#7a8793}}small{{display:block;margin-top:6px}}.scroll{{overflow:auto;border:1px solid #dce2e8;border-radius:5px;background:#fff}}table{{border-collapse:collapse;width:100%;min-width:600px;text-align:left}}th,td{{padding:14px 17px;border-bottom:1px solid #e5eaf0;vertical-align:top}}thead{{background:#f2f5f8}}th{{font-weight:550}}td p{{font-size:13px;color:#71808d}}code{{font:11px/1.8 SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}}.metadata{{padding:15px 20px;background:#fff;border:1px solid #dce2e8;border-radius:5px}}dl{{display:grid;grid-template-columns:85px 1fr;gap:8px;font-size:12px}}dt{{color:#83909a}}dd{{margin:0;overflow-wrap:anywhere}}.chart{{padding:20px;background:#fff;border:1px solid #dce2e8;border-radius:5px}}svg{{width:100%;max-height:240px}}svg text{{font:10px sans-serif;fill:#8995a0}}details{{margin-top:25px}}summary{{cursor:pointer;color:#677b88}}.note{{font-size:12px;color:#88959d;margin:12px 0 25px}}@media(max-width:650px){{main{{padding:24px 15px}}.metrics{{grid-template-columns:repeat(2,1fr)}}.metric:nth-child(2){{border-right:0}}.metric:nth-child(-n+2){{border-bottom:1px solid #e6eaef}}h1{{font-size:25px}}header{{padding:14px 20px}}}}
    </style></head><body><header><strong>modelguard</strong><span class="status {safe(status)}">{safe(status)}</span></header><main><h1>Prompt change. Measured impact.</h1><p>{safe(baseline.prompt_version)} compared with {safe(candidate.prompt_version)}</p><div class="banner">{safe(banner)}</div><section class="metrics" aria-label="Comparison metrics"><div class="metric"><strong>{percent(baseline.summary['pass_rate'])}</strong><span>Baseline pass rate</span></div><div class="metric"><strong>{percent(candidate.summary['pass_rate'])}</strong><span>Candidate pass rate</span></div><div class="metric"><strong>{delta:+.1f} pp</strong><span>Change in pass rate</span></div><div class="metric"><strong>{len(comparison['regressions'])}</strong><span>Regressed cases · {len(comparison['improvements'])} improved</span></div></section><h2>What got worse</h2><div class="scroll"><table><thead><tr><th>Case</th><th>Baseline output</th><th>Candidate output</th></tr></thead><tbody>{rows}</tbody></table></div><h2>Category accuracy</h2><div class="scroll"><table><thead><tr><th>Category</th><th>Cases</th><th>Baseline</th><th>Candidate</th><th>Delta</th></tr></thead><tbody>{cats}</tbody></table></div><h2>Run history</h2><div class="chart">{chart}</div><p class="note">Saved compatible runs, oldest to newest. Drift: {safe(drift['status'])}. A 7-run window is required by default.</p><h2>Statistical evidence</h2><p>Exact two-sided McNemar p = <strong>{comparison['mcnemar_exact_p']:.4f}</strong> on paired pass/fail changes.</p><p class="note">Warning and critical thresholds are operational percentage-point gates, not statistical significance. This p-value is exploratory; correlated cases, repeated testing and LLM judge noise limit inference.</p><details><summary>All case results ({len(candidate.cases)})</summary><div class="scroll"><table><thead><tr><th>Case</th><th>Baseline</th><th>Candidate</th><th>Summary</th><th>Latency</th></tr></thead><tbody>{allcases}</tbody></table></div></details><details><summary>Measurements and run identity</summary><div class="metadata">{metadata}</div><div class="scroll"><table><thead><tr><th>Measurement</th><th>Baseline</th><th>Candidate</th></tr></thead><tbody>{measurements}</tbody></table></div><p class="note">Tokens are observed counts only. Missing telemetry is not zero. Retried or failed requests can make usage incomplete; no dollar-cost estimate is invented.</p></details></main></body></html>'''

def write_report(directory: Path, baseline, candidate, comparison: dict, history: list, drift: dict):
    directory.mkdir(parents=True,exist_ok=True)
    payload={'comparison':comparison,'drift':drift,'baseline':baseline.model_dump(),'candidate':candidate.model_dump()}
    atomic_text(directory/'comparison.json',json.dumps(payload,indent=2,allow_nan=False)+'\n')
    atomic_text(directory/'report.html',render_html(baseline,candidate,comparison,history,drift))
    atomic_text(directory/'summary.md',f"## ModelGuard: {comparison['status']}\n\nBaseline: {percent(baseline.summary['pass_rate'])}; candidate: {percent(candidate.summary['pass_rate'])}; delta: {100*comparison['delta']:+.1f} pp.\n\n{len(comparison['regressions'])} regressions; {len(comparison['improvements'])} improvements. Drift: {drift['status']}.\n\nProvenance: {candidate.provenance}; provider: {candidate.provider}.\n")
